import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 67
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    with io.StringIO(raw_csv, newline="") as source:
        records = list(csv.reader(
            source, delimiter=",", quotechar='"', doublequote=True
        ))

    first_nonblank = None
    first_tabular = None
    header_index = None

    for index, record in enumerate(records):
        if not any(field.strip() for field in record):
            continue
        if record == ["sep=", ""]:
            continue
        if first_nonblank is None:
            first_nonblank = index
        if len(record) > 1 and first_tabular is None:
            first_tabular = index
        if len(record) == expected_width and any(
            any(char.isalpha() for char in field) for field in record[1:]
        ):
            header_index = index
            break

    if header_index is None:
        header_index = first_tabular if first_tabular is not None else first_nonblank
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    # Keep overflow fields in separate columns rather than discarding them.
    used_names = set(columns)
    while len(columns) < width:
        base = f"extra_column_{len(columns) + 1}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
